-- 497_restore_missing_sql_templates.sql — GENERATED by scripts/db/template-restore.mjs. Do not edit by hand.
--
-- Puts back the 125 message templates the Fundhub company lost (read-only production
-- read, 2026-10-20). A PG test that ran against the live database deleted them; their seed files
-- are already marked applied, so migrate alone could not restore them. Without them the welcome
-- email and text, the booking confirmation, the contract email and the document asks never send.
--
-- The copy, channel, subject and approval flag are exactly what the repo's own SQL seeds
-- produce (124 approved as seeded, 1 left unapproved as seeded).
--
-- INSERT ONLY. ON CONFLICT DO NOTHING: a template that already exists, edited or not, is never
-- touched. Nothing is updated or deleted. Inserting a template sends nothing: the only trigger on
-- message_templates is BEFORE UPDATE, and a send reads a template only when a workflow fires.

INSERT INTO message_templates (org_id, template_key, channel, subject, body, compliance_passed)
SELECT o.id, r.template_key, r.channel, r.subject, r.body, r.compliance_passed
  FROM orgs o
 CROSS JOIN jsonb_to_recordset($fh_tpl_restore$[
{"template_key":"CONTRACT-REMIND-EMAIL","channel":"email","subject":"Still waiting on your signature: {{contract.title}}","body":"Hi {{contact.first_name}},\n\nThis is a reminder about {{contract.title}}, which is still waiting for your signature.\n\nOpen it here:\n{{contract.link}}\n\nIt only takes a minute. If you have decided not to sign, there is a button on that page to say so — that is genuinely fine, and it stops these reminders.\n\nIf you have any questions about the document, reply to this email and a person will get back to you.","compliance_passed":true},
{"template_key":"CONTRACT-SEND-EMAIL","channel":"email","subject":"Please sign: {{contract.title}}","body":"Hi {{contact.first_name}},\n\n{{contract.sender}} has sent you a document to sign: {{contract.title}}.\n\nOpen it here:\n{{contract.link}}\n\nThe link is just for you — please do not forward it. It works for 30 days.\n\nYou will be able to read the whole document before you sign anything. When you sign, a copy is saved with the date and time, and you can come back to the same link to read it again whenever you like.\n\nIf you were not expecting this, or something does not look right, reply to this email and a person will get back to you.","compliance_passed":true},
{"template_key":"EMAIL-AX07-FUNDING-PAUSED","channel":"email","subject":"Funding paused — action needed","body":" Hi {{contact.first_name}},\n\n We detected a new negative item on your credit report while your funding file is in progress.\n To protect approvals, we’re pausing the funding sequence until this is handled.\n\n Next step: we need a quick call to approve the reduced-cost fix\n ( ${{contact.cf_negative_quote_amount}} ) so we can continue.\n\n Click below to book a quick call (or reply to this email if you can’t book right now).\n\n Book the quick call\n\n Note: this may extend your timeline until resolved. We’ll confirm next steps on the call.\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n {{unsubscribe}}","compliance_passed":true},
{"template_key":"EMAIL-CANDIDATE-EEO-INVITE","channel":"email","subject":"Optional equal-opportunity survey — Fundhub","body":"Hi {{candidate.first_name}},\n\nThank you for applying. Federal and local bias-audit rules ask employers to\noffer a voluntary, separate survey about race, gender, veteran status, and\ndisability. Your answers are optional. You may skip any question or decline\nto answer the whole survey.\n\nNothing you put here is shown to the people reviewing your application, and\nyour answers cannot be linked back to your name once you submit.\n\nOpen the survey here:\n{{survey.url}}\n\nIf the link does not open, copy and paste it into your browser.\n\n— Fundhub Hiring","compliance_passed":true},
{"template_key":"EMAIL-CANDIDATE-OUTREACH-1","channel":"email","subject":"We got your application — {{role.name}}","body":"Hi {{candidate.first_name}},\n\nThanks for applying for the {{role.name}} role at Fundhub. We have your application.\n\nThe next step is a short interview. You can pick a time here:\n{{role.booking_url}}\n\nIf none of those times work, reply to this email and tell us when does.\n\n— Fundhub Hiring","compliance_passed":true},
{"template_key":"EMAIL-CANDIDATE-OUTREACH-2","channel":"email","subject":"Still want to talk? — {{role.name}}","body":"Hi {{candidate.first_name}},\n\nFollowing up on your {{role.name}} application. We have not seen a time booked yet.\n\nHere is the link again:\n{{role.booking_url}}\n\nIt takes about a minute. If you have changed your mind, just reply and say so and we will close it out.\n\n— Fundhub Hiring","compliance_passed":true},
{"template_key":"EMAIL-CANDIDATE-OUTREACH-3","channel":"email","subject":"Two minutes to pick a time — {{role.name}}","body":"Hi {{candidate.first_name}},\n\nWe are still holding a spot for your {{role.name}} interview.\n\nPick any time that works:\n{{role.booking_url}}\n\nIf you would rather not go ahead, reply and tell us and we will stop emailing.\n\n— Fundhub Hiring","compliance_passed":true},
{"template_key":"EMAIL-CANDIDATE-OUTREACH-4","channel":"email","subject":"Last note about your application — {{role.name}}","body":"Hi {{candidate.first_name}},\n\nThis is the last time we will chase you about the {{role.name}} role.\n\nThe link is open if you want it:\n{{role.booking_url}}\n\nIf we do not hear from you we will leave your application where it is and stop\nemailing. You are welcome to come back to it later.\n\n— Fundhub Hiring","compliance_passed":true},
{"template_key":"EMAIL-COMMISSION-PAID","channel":"email","subject":"You got paid — {{amount_display}} is on the way","body":"Hey {{staff_first_name}},\n\nYou're paid.\n\nAmount: {{amount_display}}\nHow it's going out: {{payout_rail}}\nReference: {{payout_ref}}\n\nExpect that money to hit your account today (ACH usually same day or next bank day).\n\n— Fundhub","compliance_passed":true},
{"template_key":"EMAIL-DOC-01-REQUEST","channel":"email","subject":"Documents needed before we can start","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Documents needed before we can start</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">One thing standing between you and Round 1: documents.</p>\n            <p style=\"margin:0 0 16px 0;\">We need these before anything moves:</p>\n            <p style=\"margin:0 0 16px 0;\">• Government-issued photo ID<br>\n            • Proof of address<br>\n            • Articles of organization or incorporation, if you have an entity</p>\n            <p style=\"margin:0 0 16px 0;\">Two ways to send them:</p>\n            <p style=\"margin:0 0 16px 0;\">1. Upload in your portal: {{CLIENT_PORTAL_URL}}<br>\n            2. Text photos directly to this number</p>\n            <p style=\"margin:0 0 16px 0;\">Our system reviews them as soon as they land and tells you immediately if anything is unclear or needs a retake.</p>\n            <p style=\"margin:0 0 16px 0;\">Nothing starts until these clear — so the sooner they're in, the sooner you're moving.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-DOC-03-APPROVED","channel":"email","subject":"Documents approved — you're moving","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Documents approved — you're moving</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Your documents cleared.</p>\n            <p style=\"margin:0 0 16px 0;\">Next: we optimize your profile, then your specialist starts Round 1. You'll get a text the moment applications go out.</p>\n            <p style=\"margin:0 0 16px 0;\">Track everything here: {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-DPC05-NO-PROGRESS-72H","channel":"email","subject":"72-hour no-progress escalation","body":" Internal alert — this record has had no progress for 72+ hours .\n\n Contact: {{contact.first_name}} {{contact.last_name}}\n\n Last Progress Action: {{custom_fields.cf_last_progress_action}}\n\n Last Progress Timestamp: {{custom_fields.cf_last_progress_timestamp}}\n\n Employee Next Action: {{custom_fields.employee_next_action}}\n\n Hard Stop Reason (if any): {{custom_fields.cf_hard_stop_reason}}\n\n Required: take one decisive action now — escalate + move the file forward, or close the file if appropriate.\n\n Open Client Record\n\n This is a mechanical control alert (72-hour rule). Do not leave records idle.\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-F02-ID-PORTAL-NEEDED","channel":"email","subject":"One quick step before we can begin","body":" Hey {{contact.first_name}},\n\n Quick heads up — your onboarding isn’t fully complete yet, and we can’t start your funding rounds until it is.\n\n What we still need from you (one or both may apply):\n\n • Government ID uploaded \n\n • Portal onboarding marked complete \n\n Please use the button below to finish onboarding. Once that’s done, your file automatically moves forward.\n\n Finish Onboarding\n\n If the button doesn’t work, copy/paste this link into your browser:\n\n {{PORTAL_ONBOARDING_LINK}}\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-F02-ID-PORTAL-NEEDED-FOLLOWUP","channel":"email","subject":"P2 — ID / Portal Still Missing","body":" You’re stalling your own funding\n\n Hey {{contact.first_name}},\n\n Quick follow-up — your file is ready to move, but we’re still blocked.\n\n We still need your ID / portal onboarding completed before we can start Round 1.\n\n This is verification (lenders require it). Until it’s done, we can’t submit anything, and approvals can’t start.\n\n Knock this out here:\n\n Upload ID / Finish Onboarding\n\n If something’s stopping you, reply and tell us what it is — we’ll help fast.\n\n – {{sender_name}}\nFundHub.ai\n\n FundHub.ai • Onboarding Support\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-F03-ROUND-SUBMITTED","channel":"email","subject":"Funding Round {{custom_fields.funding_round_number}} has been submitted","body":" Hey {{contact.first_name}},\n\n Quick update — we’ve submitted Funding Round {{custom_fields.funding_round_number}} for your file.\n\n What happens next:\n\n • Lenders review the submission and return decisions on their timelines.\n\n • If anything is needed to finalize this round (identity, verification, or additional documentation), we’ll notify you as soon as it’s requested.\n\n You can monitor round status and next steps inside your client portal.\n\n View Funding Round Status\n\n If the button doesn’t work, copy/paste this link into your browser:\n\n {{CLIENT_PORTAL_URL}}\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-F04-ROUND-APPROVALS","channel":"email","subject":"Approvals are in for Funding Round {{custom_fields.funding_round_number}}","body":" Hey {{contact.first_name}},\n\n Quick update — approvals for Funding Round {{custom_fields.funding_round_number}} have started coming back and have been posted to your file.\n\n Next steps are simple:\n\n • Review the approved offers associated with this round\n\n • Complete any lender verification steps if requested (identity / security / address confirmation)\n\n • Follow the activation / access instructions tied to each approval\n\n You can view the current approvals and the exact next steps inside your client portal.\n\n View Approvals & Next Steps\n\n If the button doesn’t work, copy/paste this link into your browser:\n\n {{CLIENT_PORTAL_URL}}\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-F06-MISSING-DOCS","channel":"email","subject":"Funding is now locked — here’s what happens next","body":" Hey {{contact.first_name}},\n\n Quick update — your funding outcome is now marked Funding Locked . That means your results for this sequence have been finalized and your file is moving into the next operational step.\n\n Next steps:\n\n • Review the final approvals and any remaining activation / verification steps\n\n • Follow the access instructions tied to each approval (logins, identity checks, etc.)\n\n • Track completion inside your client portal so we can keep things moving cleanly\n\n Billing note: since this round is locked, your invoice will be issued based on the locked fee settings tied to your file.\n\n View Next Steps\n\n If the button doesn’t work, copy/paste this link into your browser:\n\n {{CLIENT_PORTAL_URL}}\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-F07-FUNDING-LOCKED","channel":"email","subject":"FR22 – Total Funding Locked","body":" Your total funding is locked 🔓\n\n Hey {{contact.first_name}},\n\n You made it. \n After 10 rounds of strategic submissions, lender sequencing, inquiry spacing, \n and profile management — your total funding is now locked in. \n\n Total funding secured:\n\n ${{total_funding_locked}}\n\n This includes the combined approvals from:\n\n Your personal funding rounds\n\n Your business funding rounds\n\n All premium-tier banks that appeared in late rounds\n\n This number is the result of discipline, timing, structure, \n and following the process exactly the way it was designed.\n\n IMPORTANT: \n Do not activate any cards yet. \n We still need to finalize your post-funding instructions to protect your profile and \n ensure smooth usage of new lines.\n\n Over the next few days, we’ll send you:\n\n Activation & optimization instructions\n\n Zero-percent usage strategies\n\n Reporting & monitoring guidance\n\n How to prepare for the next funding cycle\n\n Your next email will be: \n FR23 – Post-Funding Monitoring \n\n You executed this perfectly. \n Let’s finish strong.\n\n – {{sender_name}}\n\n FundHub.ai\n\n FundHub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-N04-POST-FUNDING","channel":"email","subject":"What comes after funding","body":" Hey {{contact.first_name}},\n\n Once funding is in place, the biggest determinant of future outcomes isn’t access — it’s how things are handled *after* the fact.\n\n We see profiles perform best when people focus on:\n\n• Maintaining clean utilization patterns \n\n• Avoiding unnecessary account noise \n\n• Letting structure and timing do the heavy lifting\n\n The goal post-funding isn’t speed — it’s stability. That’s what preserves optionality and keeps doors open down the line.\n\n Learn How to Protect Your Position\n\n Small decisions now shape what’s possible later.\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-N06-RENEWAL","channel":"email","subject":"When “second-wave” funding makes sense","body":" Hey {{contact.first_name}},\n\n A lot of entrepreneurs assume funding is a one-time event. In reality, the strongest outcomes often come from a second wave — executed with the right timing and structure.\n\n Second-wave funding tends to work best when:\n\n• Your profile has stayed stable since the last activity \n\n• Utilization and payment behavior have been clean \n\n• There’s a clear business objective (growth, liquidity, leverage)\n\n If you’re considering another round, the goal isn’t to “apply more” — it’s to re-enter the market when the signals are strongest.\n\n Check Second-Wave Readiness\n\n The right timing can change everything — this is about strategy, not speed.\n\n fundhub.ai • Funding Intelligence for Entrepreneurs\n\n Unsubscribe","compliance_passed":true},
{"template_key":"EMAIL-NOBOOK-01","channel":"email","subject":"Your application is in — the call isn't booked yet","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Your file is ready</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Your application is in and we can see your profile.</p>\n            <p style=\"margin:0 0 16px 0;\">What we can't do is tell you what it means until we get you on a call. That's the part where we go through what's fundable now, what isn't, and what order to do things in.</p>\n            <p style=\"margin:0 0 16px 0;\">It takes about 30 minutes.</p>\n            <p style=\"margin:0 0 16px 0;\">Grab a time: {{custom_values.booking_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-NOBOOK-02","channel":"email","subject":"The order matters more than the score","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>The order matters</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">One thing we see constantly: two people with nearly identical profiles get completely different results.</p>\n            <p style=\"margin:0 0 16px 0;\">Usually it comes down to sequence — which applications went out, in what order, how close together, and what was on the file at the time.</p>\n            <p style=\"margin:0 0 16px 0;\">That's what the call covers. Your file, your sequence, what to do first.</p>\n            <p style=\"margin:0 0 16px 0;\">{{custom_values.booking_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-NOBOOK-03","channel":"email","subject":"Closing this out unless you want the call","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Closing this out</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Last note from me on this.</p>\n            <p style=\"margin:0 0 16px 0;\">Your application is still on file. If you want us to walk you through it, the calendar is open. If the timing isn't right, no problem — it'll be here when it is.</p>\n            <p style=\"margin:0 0 16px 0;\">{{custom_values.booking_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-FUNDING-DFY","channel":"email","subject":"You're set up — here's what we need from you","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>You're set up</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">You're in. Here's what happens now.</p>\n            <p style=\"margin:0 0 16px 0;\">Before we can start submitting, we need your documents uploaded and approved. That's a hard gate — nothing moves until it clears.</p>\n            <p style=\"margin:0 0 16px 0;\">Upload here: {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">Once your documents are approved:</p>\n            <p style=\"margin:0 0 16px 0;\">1. We optimize your profile<br>\n            2. Your specialist starts Round 1<br>\n            3. You get a text when applications go out<br>\n            4. We clean up the resulting inquiries<br>\n            5. Repeat across the remaining rounds</p>\n            <p style=\"margin:0 0 16px 0;\">You'll hear from us at every step. Reply to this email or text us if anything is unclear.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-FUNDING-MASTERY","channel":"email","subject":"Funding Mastery — you're enrolled","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Funding Mastery — you're enrolled</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">You're enrolled. Full course is unlocked in your portal right now:<br>\n            {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">This is the whole system, A to Z — profile structure, lender sequencing, inquiry spacing, timing, and the order operations actually need to happen in.</p>\n            <p style=\"margin:0 0 16px 0;\">Work through it in order. The sequence is the point.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-NONE","channel":"email","subject":"Where things stand","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Where things stand</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Thanks for the call.</p>\n            <p style=\"margin:0 0 16px 0;\">Based on what we went through, there isn't a package we'd put you in right now. We'd rather tell you that than sell you something that won't move the needle.</p>\n            <p style=\"margin:0 0 16px 0;\">Your analysis stays in your portal: {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">Profiles change. When yours does, come back and we'll take another look.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-REPAIR-DFY","channel":"email","subject":"Your repair file is open","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Your repair file is open</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Your repair file is open.</p>\n            <p style=\"margin:0 0 16px 0;\">We work in rounds. Each round we identify what's disputable, send the letters, wait for the bureaus to respond, then reassess based on what came back.</p>\n            <p style=\"margin:0 0 16px 0;\">Your portal shows every item, every letter, and every response as it lands:<br>\n            {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">Bureaus set their own timelines, so the pace isn't ours to control. What we control is that nothing sits idle.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-REPAIR-TRIAL","channel":"email","subject":"Your first repair round is starting","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Your first repair round is starting</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Your test round is starting.</p>\n            <p style=\"margin:0 0 16px 0;\">This is one full round, done for you — we identify what's disputable, send the letters, and show you exactly what comes back from the bureaus.</p>\n            <p style=\"margin:0 0 16px 0;\">Track it here: {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">When the round closes, we'll go through the results with you and you can decide whether to keep going.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-SOFT-PULL","channel":"email","subject":"Your UnderwriteIQ assessment is running","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Your UnderwriteIQ assessment is running</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Payment received. Your UnderwriteIQ assessment is running now.</p>\n            <p style=\"margin:0 0 16px 0;\">This pulls your profile the way an underwriter sees it — structure, utilization, inquiry spacing, and what's actually driving decisions on your file.</p>\n            <p style=\"margin:0 0 16px 0;\">Results land in your portal: {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">Your advisor will walk you through what it means.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-OFFER-UWIQ-DELIVERABLES","channel":"email","subject":"Your deliverables package is being built","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Your deliverables package is being built</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">We're building your package now. Here's what's in it:</p>\n            <p style=\"margin:0 0 16px 0;\">• Credit Analysis Report<br>\n            • Dispute Letter Pack<br>\n            • Credit Optimization Roadmap<br>\n            • Funding Snapshot<br>\n            • Bank &amp; Lender Match List<br>\n            • How To Use This mini course</p>\n            <p style=\"margin:0 0 16px 0;\">Everything lands in your portal as it's finished: {{CLIENT_PORTAL_URL}}</p>\n            <p style=\"margin:0 0 16px 0;\">The mini course explains how to actually use the rest of it. Start there when it arrives.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-PARTNER-WELCOME","channel":"email","subject":"You are in — {{partner.brand}}","body":"Hi {{partner.first_name}},\n\nYou are approved as a Fundhub {{partner.kind_label}} partner.\n\nSign in here: {{partner.login_url}}\n\nYou do not have a password yet. On that page, click \"Forgot your password?\" and\nwe will email you a link to set one. The link lasts one hour.\n\nYour page: {{partner.site_url}}\n\nReply to this email if anything does not work.\n\n— Fundhub","compliance_passed":true},
{"template_key":"EMAIL-REPAIR-LETTERS-SENT","channel":"email","subject":"Your dispute letters are on the way","body":"Hi {{contact.first_name}},\n\nGood news — your dispute letters for this round are on the way.\n\nThis round covers:\n{{repair.accounts_list}}\n\nBureaus included: {{repair.bureaus_list}}\n\nWhat a bureau response looks like: a letter (or PDF) from Experian, Equifax, or TransUnion that names the accounts and says what they did (for example verified, updated, or no longer listed). When it arrives, upload it in your portal under \"Upload your bureau response.\"\n\nPortal: {{portal_login_url}}\n\nThis email describes the process. It does not promise any removal, score change, or result.\n\n— The Fundhub Team","compliance_passed":true},
{"template_key":"EMAIL-REPAIR-RESPONSE-RESULTS","channel":"email","subject":"We reviewed your bureau response","body":"Hi {{contact.first_name}},\n\nWe reviewed the bureau response you uploaded. Here is what that letter says for each account, in plain words:\n\n{{repair.outcomes_list}}\n\nWhat we do next: accounts the bureau verified or left open may move into the next dispute round when your program allows it. Accounts no longer listed or updated are closed on our side for this step.\n\nPortal: {{portal_login_url}}\n\nThis is a read of their letter — not a promise about future results.\n\n— The Fundhub Team","compliance_passed":true},
{"template_key":"EMAIL-REPAIR-RETAKE-PHOTO","channel":"email","subject":"Please retake your bureau letter photo","body":"Hi {{contact.first_name}},\n\nWe could not read the photo you uploaded. Please take a new one and upload it again under \"Upload your bureau response.\"\n\nWhat to fix:\n{{repair.retake_message}}\n\nTips: full page in frame, good light, no glare, text sharp enough to read.\n\nPortal: {{portal_login_url}}\n\n— The Fundhub Team","compliance_passed":true},
{"template_key":"EMAIL-REPAIR-ROUND-ADVANCED","channel":"email","subject":"Round {{repair.round}} is out","body":"Hi {{contact.first_name}},\n\nRound {{repair.round}} is out. These accounts are moving forward because the prior bureau answer left them open for another step:\n\n{{repair.escalated_list}}\n\nWe will prepare the next letters when they are ready to send. You will get another email when they mail.\n\nPortal: {{portal_login_url}}\n\nThis email describes the process only. It does not promise any removal, score change, or result.\n\n— The Fundhub Team","compliance_passed":true},
{"template_key":"EMAIL-REPAIR-TRIAL-COMPLETE-UPSELL","channel":"email","subject":"Your trial rounds are complete — next steps","body":"Hi {{contact.first_name}},\n\nYour trial repair rounds are complete.\n\nRecap of what we worked through:\n{{repair.results_recap}}\n\nA Fundhub team member will reach out about continuing into the full program where you left off — not starting over. Reply to this email if you have questions before then.\n\nPortal: {{portal_login_url}}\n\nThis email describes your program status. It does not promise any removal, score change, or result.\n\n— The Fundhub Team","compliance_passed":true},
{"template_key":"EMAIL-REPAIR-WELCOME","channel":"email","subject":"Welcome — here is what happens next in your repair program","body":"Hi {{contact.first_name}},\n\nWelcome to your Fundhub repair program. Here is what happens next.\n\n1. We prepare dispute letters from your credit file when your agreement is on file.\n2. When letters mail, we email you which accounts and bureaus were included.\n3. When a bureau writes back, upload that letter in your portal under \"Upload your bureau response.\" Clear photos of the full page work best.\n\nSign in here: {{portal_login_url}}\n\nThis email explains the process only. It does not promise any removal, score change, or result.\n\n— The Fundhub Team","compliance_passed":true},
{"template_key":"EMAIL-S00-WELCOME","channel":"email","subject":"You're in — here's what happens next","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>You're in</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">You're in. Here's how this works.</p>\n            <p style=\"margin:0 0 16px 0;\">Fundhub looks at your credit profile the way a lender does — structure, timing, and sequence, not just the score. Then we tell you what's realistically fundable right now and what needs to be fixed first.</p>\n            <p style=\"margin:0 0 16px 0;\">Two steps from here:</p>\n            <p style=\"margin:0 0 16px 0;\">1. Finish your application so we can see the full picture<br>\n            2. Book a call so we can walk you through what it means</p>\n            <p style=\"margin:0 0 16px 0;\">Start here: {{custom_values.booking_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">If you already did both — nothing to do. We'll be in touch.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-S02-FINISH-APPLICATION","channel":"email","subject":"You were halfway through — finish what you started","body":"Hey {{contact.first_name}},\n\nI saw you start on Fundhub and then stop before finishing. That happens — life gets loud.\n\nThat form is what we use to map what funding looks realistic for you, or what to fix first if you're not fundable yet.\n\nFinish here while it's fresh:\n{{custom_values.booking_link}}\n\nTalk soon,\nFundhub","compliance_passed":true},
{"template_key":"EMAIL-S04-01-CONFIRM","channel":"email","subject":"You're booked — {{appointment.start_time}}","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Your Fundhub call is confirmed</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\"><strong>You're booked.</strong> Here are the details:</p>\n            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"margin:0 0 20px 0;border:1px solid #E4E4E7;\">\n              <tr>\n                <td style=\"padding:12px 16px;font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#52525B;width:120px;\">When</td>\n                <td style=\"padding:12px 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#18181B;\"><strong>{{appointment.start_time}}</strong></td>\n              </tr>\n              <tr>\n                <td style=\"padding:12px 16px;font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#52525B;border-top:1px solid #E4E4E7;\">Where</td>\n                <td style=\"padding:12px 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#18181B;border-top:1px solid #E4E4E7;\">{{appointment.meeting_location}}</td>\n              </tr>\n            </table>\n            <p style=\"margin:0 0 16px 0;\">Here is your link to sign in to your Fundhub portal:</p>\n            <p style=\"margin:0 0 16px 0;\"><a href=\"{{magic_link.url}}\" style=\"color:#1D4ED8;\">{{magic_link.url}}</a></p>\n            <p style=\"margin:0 0 16px 0;\">A member of the Fundhub team will walk you through your file and the options it supports. Nothing to prepare — just be somewhere you can talk.</p>\n            <p style=\"margin:0 0 16px 0;\">Need a different time? <a href=\"{{custom_values.booking_link}}\" style=\"color:#1D4ED8;\">Reschedule here</a>.</p>\n            <p style=\"margin:0 0 8px 0;\">See you then,<br>The Fundhub Team</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-S05A-NOSHOW-02","channel":"email","subject":"Still holding your analysis","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Still holding your analysis</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">We missed you yesterday. Your file is still here and nothing's changed on our end.</p>\n            <p style=\"margin:0 0 16px 0;\">Pick a time that actually works and we'll go through it:<br>\n            {{reschedule_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-S05A-NOSHOW-03","channel":"email","subject":"Do you still want this?","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Do you still want this?</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">Straight question: do you still want to go through your analysis, or has the timing changed?</p>\n            <p style=\"margin:0 0 16px 0;\">Either answer works. We just don't want to keep reaching out if you're not in a position to move on it right now.</p>\n            <p style=\"margin:0 0 16px 0;\">If you are: {{reschedule_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
{"template_key":"EMAIL-S05A-NOSHOW-04","channel":"email","subject":"Closing your file for now","body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<title>Closing your file for now</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F4F4F5;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;\">\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"background-color:#F4F4F5;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\" style=\"max-width:600px;background-color:#FFFFFF;border:1px solid #E4E4E7;\">\n        <tr>\n          <td style=\"padding:28px 28px 8px 28px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#18181B;\">\n            <p style=\"margin:0 0 16px 0;\">Hey {{contact.first_name}},</p>\n            <p style=\"margin:0 0 16px 0;\">We're closing this out for now.</p>\n            <p style=\"margin:0 0 16px 0;\">Your analysis stays saved in your portal — nothing gets deleted. If the timing changes, the calendar's always open.</p>\n            <p style=\"margin:0 0 16px 0;\">{{reschedule_link}}</p>\n            <p style=\"margin:0 0 16px 0;\">Good luck out there.</p>\n            <p style=\"margin:0 0 16px 0;\">{{sender_name}}<br>\n            Fundhub</p>\n            <p style=\"margin:0 0 16px 0;\">fundhub.ai • Funding Intelligence for Entrepreneurs<br>\n            {{unsubscribe}}</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>","compliance_passed":true},
